2443: static void
2444: bare_fs__on_watcher_event(uv_fs_event_t *handle, const char *filename, int events, int status) {
2445:   int err;
2446: 
2447:   bare_fs_watcher_t *watcher = (bare_fs_watcher_t *) handle;
2448: 
2449:   if (watcher->exiting) return;
2450: 
2451:   js_env_t *env = watcher->env;
2452: 
2453:   js_handle_scope_t *scope;
2454:   err = js_open_handle_scope(env, &scope);
2455:   assert(err == 0);
2456: 
2457:   js_value_t *ctx;
2458:   err = js_get_reference_value(env, watcher->ctx, &ctx);
2459:   assert(err == 0);
2460: 
2461:   js_value_t *on_event;
2462:   err = js_get_reference_value(env, watcher->on_event, &on_event);
2463:   assert(err == 0);
2464: 
2465:   js_value_t *args[3];
2466: 
2467:   if (status < 0) {
2468:     js_value_t *code;
2469:     err = js_create_string_utf8(env, (utf8_t *) uv_err_name(status), -1, &code);
2470:     assert(err == 0);
2471: 
2472:     js_value_t *message;
2473:     err = js_create_string_utf8(env, (utf8_t *) uv_strerror(status), -1, &message);
2474:     assert(err == 0);
2475: 
2476:     err = js_create_error(env, code, message, &args[0]);
2477:     assert(err == 0);
2478: 
2479:     err = js_create_int32(env, 0, &args[1]);
2480:     assert(err == 0);
2481: 
2482:     err = js_get_null(env, &args[2]);
2483:     assert(err == 0);
2484:   } else {
2485:     err = js_get_null(env, &args[0]);
2486:     assert(err == 0);
2487: 
2488:     err = js_create_int32(env, events, &args[1]);
2489:     assert(err == 0);
2490: 
2491:     size_t len = strlen(filename);
2492: 
2493:     void *data;
2494:     err = js_create_arraybuffer(env, len, &data, &args[2]);
2495:     assert(err == 0);
2496: 
2497:     memcpy(data, (void *) filename, len);
2498:   }
2499: 
2500:   err = js_call_function(env, ctx, on_event, 3, args, NULL);
2501:   (void) err;
2502: 
2503:   err = js_close_handle_scope(env, scope);
2504:   assert(err == 0);
2505: }
2506: 
2507: static void
2508: bare_fs__on_watcher_close(uv_handle_t *handle) {
2509:   int err;
2510: 
2511:   bare_fs_watcher_t *watcher = (bare_fs_watcher_t *) handle;
2512: 
2513:   js_env_t *env = watcher->env;
2514: 
2515:   js_deferred_teardown_t *teardown = watcher->teardown;
2516: 
2517:   if (watcher->exiting) {
2518:     err = js_delete_reference(env, watcher->on_event);
2519:     assert(err == 0);
2520: 
2521:     err = js_delete_reference(env, watcher->on_close);
2522:     assert(err == 0);
2523: 
2524:     err = js_delete_reference(env, watcher->ctx);
2525:     assert(err == 0);
2526:   } else {
2527:     js_handle_scope_t *scope;
2528:     err = js_open_handle_scope(env, &scope);
2529:     assert(err == 0);
2530: 
2531:     js_value_t *ctx;
2532:     err = js_get_reference_value(env, watcher->ctx, &ctx);
2533:     assert(err == 0);
2534: 
2535:     js_value_t *on_close;
2536:     err = js_get_reference_value(env, watcher->on_close, &on_close);
2537:     assert(err == 0);
2538: 
2539:     err = js_delete_reference(env, watcher->on_event);
2540:     assert(err == 0);
2541: 
2542:     err = js_delete_reference(env, watcher->on_close);
2543:     assert(err == 0);
2544: 
2545:     err = js_delete_reference(env, watcher->ctx);
2546:     assert(err == 0);
2547: 
2548:     err = js_call_function(env, ctx, on_close, 0, NULL, NULL);
2549:     (void) err;
2550: 
2551:     err = js_close_handle_scope(env, scope);
2552:     assert(err == 0);
2553:   }
2554: 
2555:   err = js_finish_deferred_teardown_callback(teardown);
2556:   assert(err == 0);
2557: }
